SELECT * FROM (SELECT q.*, ROW_NUMBER() OVER (PARTITION BY q."deal_id", q."tranche_name" ORDER BY q."order_demand_qty" DESC, q."investor_name" ASC, q."investor_id" ASC, q."transaction_id" ASC, q."deal_name" ASC, q."pricing_date" ASC, q."order_allocation" ASC, q."currency" ASC) AS "rank_in_group" FROM (SELECT "investor_name" AS "investor_name", "investor_gp_id" AS "investor_id", "transaction_id" AS "transaction_id", "deal_id" AS "deal_id", "deal_name" AS "deal_name", "pricing_ts" AS "pricing_date", "tranche_name" AS "tranche_name", "order_demand_qty" AS "order_demand_qty", "order_allocation" AS "order_allocation", "currency" AS "currency", COUNT("order_id") AS "row_count" FROM "bds_dg_oraas"."dgstream"."vw_order_detail" WHERE "product" = __P_f0__ AND "transaction_id" = __P_f1__ GROUP BY "investor_name", "investor_gp_id", "transaction_id", "deal_id", "deal_name", "pricing_ts", "tranche_name", "order_demand_qty", "order_allocation", "currency") q) ranked WHERE "rank_in_group" <= 5 ORDER BY "order_demand_qty" DESC, "investor_name" ASC, "deal_id" ASC, "tranche_name" ASC, "rank_in_group" ASC LIMIT 50
